utton-secondary" href="<?=tnl_escape($self)?>&amp;view=inbox">Volver a la bandeja</a></section><?php endif;?>
<?php elseif($view==='sent'):?>
<section class="panel mail-surface" data-live-region="external-list"><?php if($sent):?><div class="mail-list-heading"><span>Destinatario</span><span>Asunto</span><span>Fecha</span></div><div class="mail-list"><?php foreach($sent as $m):?><div class="mail-row"><span class="mail-sender" title="<?=tnl_escape($m['recipient'])?>"><?=tnl_escape($m['recipient'])?></span><a class="mail-subject" href="<?=tnl_escape($self)?>&amp;view=sentread&amp;id=<?=(int)$m['id']?>"><?=tnl_escape($m['subject'])?></a><time class="mail-date" title="<?=tnl_escape($m['created_at'])?>"><?=tnl_escape($m['created_at'])?></time><a class="button button-ghost" href="<?=tnl_escape($printBase)?>&amp;source=sent&amp;id=<?=(int)$m['id']?>" target="_blank" rel="noopener">Imprimir / PDF</a></div><?php endforeach;?></div><?php else:?><div class="empty-state"><span class="card-icon"><?=\TNL\UI\Workspace::icon('send')?></span><h2>Tus próximos mensajes, aquí</h2><p>Los correos que envíes desde TNL Mail aparecerán en esta lista.</p><?php if($canSend):?><a data-compose-modal class="button" href="<?=tnl_escape($self)?>&amp;view=compose">Escribir un mensaje</a><?php endif;?></div><?php endif;?></section><p class="content-note">Copias locales de los últimos envíos desde TNL Mail; no es la carpeta Enviados del servidor IMAP.</p>
<?php elseif($inbox!==null):?><?php if(!empty($inbox['spam_hidden'])):?><p class="notice"><?=(int)$inbox['spam_hidden']?> mensajes ocultos por tus reglas de spam; <?=(int)$inbox['spam_moved']?> movidos a la carpeta Spam.</p><?php endif;?>
<section class="panel mail-surface" data-live-region="external-list"><?php if($inbox['messages']):?><div class="mail-list-heading"><span>Remitente</span><span>Asunto</span><span>Fecha</span></div><div class="mail-list"><?php foreach($inbox['messages'] as $m):?><?php if(!empty($m['sent_id'])):?><a class="mail-row <?=!empty($m['unread'])?'unread':''?>" href="<?=tnl_escape($self)?>&amp;view=sentread&amp;id=<?=(int)$m['sent_id']?>"><span class="mail-sender"><?=tnl_escape($m['from'])?></span><span class="mail-subject"><?=tnl_escape($m['subject'])?><?=!empty($m['unread_count'])?' · '.(int)$m['unread_count'].' nuevos':''?></span><time class="mail-date"><?=tnl_escape($m['date'])?></time></a><?php continue;endif;?><div class="mail-row-wrap"><input type="checkbox" class="mail-select" aria-label="Seleccionar mensaje"><button type="button" class="mail-actions-toggle button-ghost" aria-label="Acciones del mensaje" aria-expanded="false" data-mail-actions>⋯</button><a class="mail-row <?=!empty($m['unread'])?'unread':''?>" href="<?=tnl_escape($self)?>&amp;view=inbox&amp;uid=<?=$m['uid']?>"><span class="mail-sender" title="<?=tnl_escape($m['from'])?>"><?=tnl_escape($m['from'])?></span><span class="mail-subject"><?=tnl_escape($m['subject'])?><?=!empty($m['unread_count'])?' · '.(int)$m['unread_count'].' nuevos':''?></span><time class="mail-date" title="<?=tnl_escape($m['date'])?>"><?=tnl_escape($m['date'])?></time></a><form method="post" class="mail-row-actions"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="uid" value="<?=(int)$m['uid']?>"><input type="hidden" name="validity" value="<?=(int)($inbox['validity']??0)?>"><a class="button button-ghost" href="<?=tnl_escape($printBase)?>&amp;uid=<?=(int)$m['uid']?>" target="_blank" rel="noopener">Imprimir / PDF</a><?php if($folderKey==='trash'):?><button class="button-ghost" name="action" value="restore">Restaurar</button><button class="button-ghost" name="action" value="delete">Borrar · copia en administración</button><?php else:?><?php if($folderKey!=='archive'):?><button class="button-ghost" name="action" value="archive">Archivar</button><?php endif;?><button class="button-ghost" name="action" value="trash">Papelera</button><?php endif;?><?php if($folderKey==='spam'):?><button class="button-ghost" name="action" value="notspam">No es spam</button><?php elseif($spamPolicy->address($m['from'])!==''&&!$spamPolicy->company($spamPolicy->address($m['from']))):?><button class="button-ghost" name="action" value="spam">Marcar spam</button><?php endif;?></form></div><?php endforeach;?></div><footer class="pagination"><span><?=$inbox['total']?> <?=$inbox['total']===1?'mensaje':'mensajes'?> · Página <?=$inbox['page']?></span><div class="pagination-links"><?php if($inbox['page']>1):?><a href="<?=tnl_escape($self)?>&amp;view=inbox&amp;page=<?=$inbox['page']-1?>">← Más recientes</a><?php endif;?><?php if($inbox['page']*20<$inbox['total']):?><a href="<?=tnl_escape($self)?>&amp;view=inbox&amp;page=<?=$inbox['page']+1?>">Más antiguos →</a><?php endif;?></div></footer><?php else:?><div class="empty-state"><span class="card-icon"><?=\TNL\UI\Workspace::icon('mail')?></span><h2>Tu bandeja está vacía</h2><p>Cuando recibas un mensaje, podrás leerlo y responder desde aquí.</p><a class="button button-secondary" href="<?=tnl_escape($self)?>&amp;view=inbox">Actualizar bandeja</a></div><?php endif;?></section>
<?php else:?><section class="panel empty-state"><h2>No se pudo cargar la bandeja</h2><p>Puedes volver a intentarlo o revisar la conexión de tu cuenta.</p><a class="button button-secondary" href="<?=tnl_escape($self)?>&amp;view=inbox">Volver a intentar</a></section><?php endif;?><?php if($view==='sent'){$history=\TNL\Mail\Dispatch::recent($db,$as.':'.$id);if($history):?><details class="panel"><summary>Envíos y reenvíos recientes</summary><?php foreach($history as $entry):?><p><strong><?=tnl_escape($entry['subject'])?></strong> · <?=$entry['kind']==='forward'?'Reenvío':'Envío'?> · <?=tnl_escape($entry['created_at'])?><br><?=tnl_escape(\TNL\Mail\Dispatch::summary(['results'=>json_decode($entry['result'],true)]))?></p><?php endforeach;?></details><?php endif;}?></main></div></body></html>
